"""
Commissioning
"""
import os
import time
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.oam.mzoam.mzoam_base import MzoamBaseClass

logger = BackgroundLogger.Instance()


class Commissioning(MzoamBaseClass):
    """
    Commissioning
    """
    def __init__(self):
        super(Commissioning, self).__init__()
        # self.commission = commissioning()
        # self.cell_operations = CellOperations()

    def perform_commissioning(self, **kwargs):
        """ This keyword commissions bts with the scf file passed via pybot, and checks for
        BTS status
            :param skip_parameter_relation_errors: Skip parameter relation errors
            :param timeout: Time to wait for positive procedure result
            :param wait_for_onair_status: Time to wait, before checking for Cell status
            :param alias: Name of execution context
        """
        scf_file = kwargs.get("scf_file", None)
        self.check_for_ignore_args(ignore_list=["skip_parameter_relation_errors"], **kwargs)
        verify_bts_status = kwargs.get("verify_bts_status", True)
        timeout = kwargs.get("timeout", 300)
        wait_for_onair_status = kwargs.get("wait_for_onair_status", 900)
        alias = kwargs.get("alias", "default")

        chained = global_vars.alias_chained_dict.get(alias, None)
        dut = global_vars.alias_dut_dict[alias]
        url = self.base_url + "{}/".format(get_config_variable([dut, 'ip']))
        if chained:
            bts_id = get_config_variable([dut, 'bts_id'])
            scf_dir = get_config_variable(['chained_bts_scf_dir']).format(chained=bts_id)
        else:
            bts_id = get_config_variable(['bts_id'])
            scf_dir = get_config_variable(['scfc_path'])
        logger.debug("btsid :: {0}\tscf_dir :: {1}".format(bts_id, scf_dir))
        if scf_file is not None:
            scf_file = os.path.join(scf_dir, scf_file)
        else:
            scf_file = os.path.join(scf_dir, get_config_variable(['scfc_name']))
        logger.debug('Scf_file', scf_file)
        logger.debug("Beginning commissioning operation...")
        self.mzom_client.perform_commissioning(scf_file, session=alias)
        logger.debug("Commissioning performed")
        # BTS STATUS AND CELL STATUS TO BE ADDED
        # Not adding now as the API is not quiet clear
        # As a WA adding get sw version
        self._wait_until_sw_version_retrieved(url, timeout=timeout, interval=1, alias=alias)

    def _wait_until_sw_version_retrieved(self, url, timeout=300, interval=30, alias="default"):
        wait_time_for_unavailability = 120
        self.mzom_client.wait_for_site_unavailability(url, wait_time_for_unavailability,
                                                      interval=1.0)
        end = time.time() + timeout
        while time.time() < end:
            try:
                sw_info = self.get_sw_versions(session=alias)
                if sw_info is not None:
                    logger.info("\nBTS Software Information: {}".format(sw_info))
                    break
            except Exception as get_sw_version_error:
                logger.warn("Couldn't retrieve software version due to {}..Bts still not up ..."
                            "Retrying....".format(get_sw_version_error))
            time.sleep(interval)
